        public static string AddFlavourToShipBook(string BookPrompt)
        {
            //Flavours that add variation between generations
            List<string> PromptOptions = new List<string>
            {
                "Include hints of romantic tension—unspoken crushes, forbidden relationships, jealousy, or awkward encounters.",
                "Mention a scandalous rumor circulating aboard the ship and how they personally feel about the people involved.",
                "Include vivid details about their daily life on the ship, their private thoughts, and how they feel about recent events.",
                "Incorporate flavorful gossip or rumors they’ve heard about other people encountered during their travels.",
                "Describe sensory details of life aboard the ship—smells, sounds, cramped quarters, rituals.",
                "Reveal an internal conflict or personal dilemma they are struggling with, showing how it shapes their decisions and mood.",
                "Describe their relationships with specific crew members—alliances, grudges, secrets, or unspoken tensions.",
                "Let their cultural background, upbringing, or past experiences influence how they interpret events and express themselves.",
                "Give their writing a distinctive verbal style—slang, metaphors, pacing, or quirks that reflect who they are.",
                "Have them reflect on a recent incident aboard the ship or during their travels, revealing how it affected them personally.",
                "Include subtle hints of unease, suspicion, or foreshadowing about something they believe is about to happen.",
                "Allow moments of honest vulnerability—fears, regrets, insecurities—that they would only admit in a private diary.",
                "Add small worldbuilding details such as customs, slang, ship traditions, or local myths they’ve encountered.",
                "Include mentions of their personal goals, ambitions, or hidden desires, and how the journey affects their pursuit of them.",
                "Describe how the environment affects them physically—fatigue from long shifts, discomfort from ship movement, or reactions to alien climates.",
                "Suggest that someone aboard the ship might be sabotaging others, spreading lies, or hiding a betrayal.",
                "Describe any power struggles, favoritism, or political maneuvering happening within the crew ranks.",
                "Include a moment where someone had an emotional outburst—anger, tears, panic—and explain the fallout.",
                "Highlight social tensions between crew factions, cliques, or individuals who simply can’t stand each other.",
                "Show how misunderstandings or half-heard conversations have sparked distrust or paranoia among the crew.",
                "Include petty rivalries—competition over duties, attention, rank, or even trivial things like cabin space.",
                "Have them reveal a secret they overheard or discovered accidentally—something they know could cause trouble if exposed.",
                "Include an awkward or embarrassing interaction with someone they’re attracted to, and their overthinking afterward.",
                "Have them struggle with unrequited love or uncertainty about whether their feelings are returned.",
                "Let memories of a past lover influence how they view new relationships or romantic opportunities.",
                "Hint at secret late-night conversations or hidden rendezvous away from prying eyes on the ship.",
                "Capture their emotional confusion—torn between desire, duty, fear, or loyalty—regarding someone they care for.",
                "Have them reflect on a strained or complicated relationship with a parent and how it affects their choices today.",
                "Mention ongoing or unresolved rivalry with a sibling—competition, bitterness, or jealousy that still lingers.",
                "Describe the pressure of family expectations weighing on them and their fear of disappointing those back home.",
                "Include memories of arguments or ideological clashes with older family members that shaped their worldview.",
                "Have them hint at a dark or embarrassing family secret they fear others might discover.",
                "Describe an estranged family member they haven’t spoken to in years, along with guilt or resentment about the silence.",
                "Include the burden of inheriting a family legacy—duties, debts, curses, or a name they struggle to live up to.",
                "Show their anxiety about family members far away—illness, danger, conflict—and their helplessness being unable to assist.",
                "Have them react to receiving unexpected family news—a letter, rumor, or message—that stirs old wounds.",
                "Have them describe the everyday chores or repetitive tasks they performed today and how tedious or oddly satisfying they found them.",
                "Include small annoyances—misplaced tools, squeaky doors, lukewarm meals, or a crew member’s irritating habits.",
                "Have them comment on the day’s weather or ship conditions and how it subtly influenced their mood.",
                "Mention simple, routine interactions—brief conversations, polite nods, shared meals—that give a sense of normalcy.",
                "Describe mundane self-care: cleaning clothes, patching gear, trimming hair, or trying to get some decent sleep.",
                "Have them note what they ate or drank today, how it tasted, and any small pleasures or disappointments.",
                "Have them describe a personal or family tradition they try to uphold even while far from home, and how it comforts them.",
                "Include a memory of a cultural ritual or celebration they miss, reflecting on how different it feels to be away during that time.",
                "Have them participate in a small shipboard tradition—old, improvised, or silly—and note how it strengthens crew camaraderie.",
                "Describe a tradition unique to their homeland, and how others react when they explain or attempt to recreate it.",
                "Include a moment where they break a long-standing tradition, willingly or not, and wrestle with the guilt or freedom that follows.",
                "Have them reflect on a tradition they once disliked but now cherish, realizing how much it shaped their identity.",
                "Describe them teaching someone else a tradition, passing down knowledge that feels fragile but important to preserve.",
                "Include a reflection on a tradition that has changed over time, and their struggle to accept or reject this new version of it.",
                "Have them question whether certain traditions still serve a purpose, or if they continue only out of habit or pressure.",
                "Describe a newly emerging tradition aboard the ship, something small but meaningful that helps the crew feel like a family.",
                "Include minor logistical tasks—inventory checks, paperwork, reorganizing supplies, running slow errands around the ship.",
                "Have them describe cleaning or organizing their bunk space, noting small frustrations or tiny comforts they discovered.",
                "Include a mention of them waiting in a long line—mess hall, supply depot, or wash station—and their thoughts while idling.",
                "Describe them dealing with a mildly broken item—stuck locker, jammed drawer, loose hinge—and their attempt to fix or ignore it.",
                "Have them comment on doing basic personal grooming—trimming nails, combing hair, or cleaning boots—and how oddly calming or boring it felt.",
                "Include a moment where they search for a misplaced everyday item and grumble about how often this seems to happen.",
                "Describe them washing or mending a piece of clothing, noticing stains, tears, or smells picked up during the day.",
                "Have them note the repetitive sounds around them—dripping pipes, humming engines, footsteps in the corridor—and how they blend into routine life.",
                "Include a short reflection on a dull shift where nothing noteworthy happened, yet they found themselves daydreaming anyway.",
                "Mention a simple shared meal with the crew, focusing on the plain food, casual chatter, and comfortable ordinariness of it.",
                "Have them question whether they are becoming the person they once hoped to be, revealing doubts or pride in their growth.",
                "Include a moment where they analyze their recent decisions, wondering if they acted out of fear, desire, or obligation.",
                "Have them reflect on a personal flaw they’ve noticed—impatience, jealousy, pride—and how it affects their relationships.",
                "Describe them contemplating a past mistake that still haunts them, and what they would do differently if given the chance.",
                "Include a reflection on what they truly value—loyalty, freedom, safety, adventure—and how the journey tests those beliefs.",
                "Have them assess their emotional state, noting what has changed within them over time and what remains stubbornly the same.",
                "Include thoughts about whether they deserve the good or bad things happening around them, revealing guilt or gratitude.",
                "Have them compare who they were before the voyage to who they are now, acknowledging subtle or dramatic shifts in identity.",
                "Describe them wrestling with uncertainty about their future, questioning where they belong and what purpose they serve.",
                "Have them reflect on a moment of unexpected joy, comfort, or peace, and how rare or precious such moments feel to them.",
                "Have them recognize a small moment of peace or comfort that made them feel like they’re finally beginning to heal.",
                "Include a reflection on someone who has recently helped them emotionally, even in ways they didn’t expect.",
                "Describe them forgiving themselves for a past mistake, or at least taking the first uncertain steps toward forgiveness.",
                "Have them acknowledge progress they’ve made—subtle changes in how they react, think, or cope compared to before.",
                "Include a moment where they let go of something they’ve been clinging to—anger, guilt, fear—and feel lighter for it.",
                "Have them realize they no longer feel as alone as they once did, thanks to new bonds or gentle kindness from others.",
                "Describe them embracing vulnerability, allowing themselves to feel sadness or hope without judgment.",
                "Have them reflect on advice someone gave them, recognizing that it brought clarity or comfort when they needed it most.",
                "Include a realization that they deserve happiness or healing, even if accepting that truth still feels strange.",
                "Have them acknowledge that healing does not mean forgetting, and that some wounds still ache even as they begin to close.",
                "Include a moment where they accept a painful truth about themselves, realizing that facing it is the only way forward.",
                "Describe them confronting a memory they’ve avoided, letting it hurt so it can finally lose some of its power over them.",
                "Have them realize that some relationships cannot be repaired, and the grief of that acceptance becomes part of their healing.",
                "Include a reflection on how suffering has reshaped them, leaving marks they may never erase but can learn to live with.",
                "Have them find strength in surviving something that once broke them, even if the pride feels uncomfortable or undeserved.",
                "Describe them letting go of a hope that has long tormented them, finding grim relief in finally releasing it.",
                "Have them face the consequences of their own actions, accepting responsibility as a painful but necessary step toward growth.",
                "Include a moment where they recognize that healing sometimes feels like numbness, and wonder if that’s progress or simply survival.",
                "Have them admit that they are still angry or afraid, but that these emotions no longer rule them the way they once did.",
                "Have them notice a small habit or ritual that has quietly helped them cope—journaling, breathing, watching the stars—and how it soothes them.",
                "Describe them getting briefly annoyed or amused by something trivial, such as a crewmate’s loud chewing or mismatched socks."
            };
            Random random = new Random();

            int count = 1 + random.Next(5);

            var selected = PromptOptions
                .OrderBy(x => random.Next())
                .Take(count);

            foreach (var prompt in selected)
            {
                BookPrompt += prompt + " ";
            }

            return BookPrompt;
        }

